  const [{ Interact }, legacyPresets, presets] = await Promise.all([
    import(`https://cdn.jsdelivr.net/npm/@wix/interact@2.8.2/dist/es/web.min.js`),
    import(`https://cdn.jsdelivr.net/npm/@wix/wix-motion-presets@1.10.0/+esm`),
